export const initialState = Object.freeze({load:'row', rowCount:3, powerFactor:1, balanced:true, faultStage:'normal', diagnosisStage:'fault'});
const read = id => `../index.html#d04-${id}`;
const labels = {"distribution-purpose": "Campus to rack", "campus-route": "Trace the load", "one-line": "Single-line diagrams", "switchgear-anatomy": "Inside switchgear", "protection-relay": "Relay and breaker", "isolation-surge": "Disconnect the transformer", "surge-protection": "Surge protection", "busway-introduction": "What is a busway?", "compass-skid": "Compass integrated skid", "local-stepdown": "Transformer location", "building-branches": "Building branches", "distribution-units": "Floor PDU, rack PDU, PSU", "busway-branches": "Busway and tap-offs", "fujitsu-busway": "Fujitsu busway", "row-growth": "Shared conductor capacity", "power-factor": "Power factor", "phase-loading": "Phase imbalance", "feeder-diagnosis": "Failed interruption", "distribution-handoff": "Continuity handoff"};
